     * @param  array{authCode?: string, dnsEntries?: list<array{name: string, expire: int, type: string, content: string}>, nameservers?: list<array{hostname: string, ipv4?: string|null, ipv6?: string|null}>, contacts?: list<array{type: string, firstName: string, lastName: string, companyName: string, companyKvk: string, companyType: string, street: string, number: string, postalCode: string, city: string, phoneNumber: string, faxNumber?: string|null, email: string, country: string}>}  $data
